export function localize(root=document.body){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  while(walker.nextNode()){
    const node=walker.currentNode;
    if(node.parentElement?.closest('script,style,pre,code,textarea,.code,[data-no-translate]'))continue;
    const previous=originals.get(node);
    const original=previous&&node.nodeValue===previous.rendered?previous.source:node.nodeValue,trimmed=original.trim().replace(/^·\s*/, '');
    if(!AR[trimmed])continue;
    const replacement=original.replace(trimmed,translate(trimmed));
    originals.set(node,{source:original,rendered:replacement});
    if(node.nodeValue!==replacement)node.nodeValue=replacement;
  }
  root.querySelectorAll('[aria-label],[placeholder]').forEach(element=>{
    if(element.closest('script,style,pre,code,.code,[data-no-translate]'))return;
    const attributes=originalAttributes.get(element)??{};
    for(const name of ['aria-label','placeholder']){
      const value=element.getAttribute(name),previous=attributes[name];
      const source=previous&&value===previous.rendered?previous.source:value;
      if(!AR[source]){delete attributes[name];continue;}
      const rendered=translate(source);
      attributes[name]={source,rendered};
      if(value!==rendered)element.setAttribute(name,rendered);
    }
    originalAttributes.set(element,attributes);
  });
}
export function observeLocalization(root=document.body){localize(root);const observer=new MutationObserver(()=>localize(root));observer.observe(root,{childList:true,subtree:true,characterData:true});return observer;}
